create extension if not exists pgcrypto;
create table if not exists donors(id uuid primary key default gen_random_uuid(),first_name text not null,last_name text not null,email text not null,phone text,country text not null,created_at timestamptz not null default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,target_usd numeric(12,2) not null,status text not null default 'Fundraising');
create table if not exists donations(id uuid primary key default gen_random_uuid(),reference text unique not null,donor_id uuid not null references donors(id),project_id uuid not null references projects(id),amount_usd numeric(12,2) not null check(amount_usd>0),frequency text not null,payment_method text not null,status text not null default 'PENDING',public_display boolean not null default false,created_at timestamptz not null default now(),verified_at timestamptz);
create table if not exists ledger(id uuid primary key default gen_random_uuid(),donation_id uuid not null references donations(id),entry_type text not null,amount_usd numeric(12,2) not null,created_at timestamptz not null default now());
create table if not exists receipts(id uuid primary key default gen_random_uuid(),donation_id uuid unique not null references donations(id),receipt_number text unique not null,issued_at timestamptz not null default now());
create table if not exists audit_log(id uuid primary key default gen_random_uuid(),actor text,action text not null,entity_type text not null,entity_id uuid,metadata jsonb,created_at timestamptz not null default now());
